MAP
    NAME "SS_MAP_DREN_ZONAS_ALCANTARILLADO"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_zonas_alcantarillado.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_DREN_ZONAS_ALCANTARILLADO_UBICACIONES"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        INCLUDE 'includes/conexion.map'  
        DATA "geometry from (select gid,geometry,('Zona de Alcantarillado: ' || numero || ' Supervisor: ' || supervisor || ' Captura: ' || captura) as txt from zonas_alcantarillado) as tmp using unique gid using srid=32614"
        STATUS DEFAULT
        TYPE POLYGON
        LABELITEM "txt"
        CLASS
            NAME "Zonas de Alcantarillado"
            STYLE
                OUTLINECOLOR 110 0 110
                WIDTH 4.0
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT ARIAL
                SIZE 19
                PARTIALS FALSE
                COLOR 110 0 110
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
    END #LAYER
END #MAP